<?php
// Protected account summary page: retrieves and displays the signed-in customer’s demo accounts and balances.
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_login(); require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/helpers.php';
$pdo = db(); $stmt = $pdo->prepare('SELECT * FROM accounts WHERE user_id = ? ORDER BY id'); $stmt->execute([$_SESSION['user_id']]); $accounts = $stmt->fetchAll();
foreach ($accounts as &$account) { $activity = $pdo->prepare('SELECT description, amount, transaction_date FROM transactions WHERE account_id = ? ORDER BY transaction_date DESC LIMIT 2'); $activity->execute([$account['id']]); $account['activity'] = $activity->fetchAll(); } unset($account);
$pageTitle = 'My Accounts'; $portal = true; require __DIR__ . '/includes/header.php';
?>
<section class="portal-shell"><div class="portal-welcome"><div><p class="eyebrow">My accounts</p><h1>All your accounts, clearly arranged.</h1><p>Balances and activity are fictional demonstration data.</p></div><a class="button" href="transfer.php">Transfer money →</a></div><div class="account-detail-list"><?php foreach ($accounts as $account): ?><article class="account-detail"><div class="account-detail-head"><div><span class="account-pill <?= e(account_badge_class($account['account_type'])) ?>"><?= e($account['account_type']) ?></span><h2><?= e($account['account_type']) ?> Account</h2><p><?= e(mask_account($account['account_number'])) ?></p></div><div class="account-balance"><span>Current balance</span><strong><?= money($account['balance']) ?></strong><small>Available: <?= money($account['balance']) ?></small></div></div><div class="account-detail-footer"><span class="status-active"><i></i><?= e($account['status']) ?></span><div class="mini-activity"><?php foreach ($account['activity'] as $activity): ?><span><?= e($activity['description']) ?> <b><?= (float)$activity['amount'] >= 0 ? '+' : '−' ?><?= money(abs((float)$activity['amount'])) ?></b></span><?php endforeach; ?></div><a class="text-action" href="transactions.php">Activity →</a></div></article><?php endforeach; ?></div></section>
<?php require __DIR__ . '/includes/footer.php'; ?>
